CREATE OR ALTER TRIGGER dbo.trg_SinhVien_Insert
ON dbo.SinhVien
AFTER INSERT
AS
BEGIN
    SET NOCOUNT ON;
    INSERT INTO dbo.AuditLog(Action, MaSV, NewDiemTB)
    SELECT 'INSERT', i.MaSV, i.DiemTB
    FROM inserted i;
END;

